//#region src/lib/geometry.ts
const TAU = Math.PI * 2;
/**
* Arena's `orientation`: the angle of the quad's top edge, in radians.
*
* Zero for any unrotated rectangle, because corner 0 -> corner 1 points along
* +x. A slice rotated by hand in Arena writes both its rotated corners AND this
* angle, and the two agree — so we derive it rather than storing it.
*/
function orientationOf(q) {
	return Math.atan2(q[1].y - q[0].y, q[1].x - q[0].x);
}
/** Bilinear sample of a quad. u runs corner0->corner1, v runs corner0->corner3. */
function bilinear(q, u, uv) {
	const iu = 1 - u;
	const iv = 1 - uv;
	return {
		x: iu * iv * q[0].x + u * iv * q[1].x + u * uv * q[2].x + iu * uv * q[3].x,
		y: iu * iv * q[0].y + u * iv * q[1].y + u * uv * q[2].y + iu * uv * q[3].y
	};
}
/**
* The control grid Arena writes for an unwarped slice: the output quad sampled
* on a regular (cols x rows) lattice, row-major, v increasing down the rows.
*/
function bilinearLattice(q, cols, rows) {
	const pts = [];
	for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) pts.push(bilinear(q, cols === 1 ? 0 : c / (cols - 1), rows === 1 ? 0 : r / (rows - 1)));
	return pts;
}

