/** Suggested filename for a target, matching where Arena expects to find it. */
function exportFilename(project, target) {
	const safe = (project.name.trim() || "output-map").replace(/[^\w .-]+/g, "_");
	return target === "preset" ? `${safe}.xml` : "AdvancedOutput.xml";
}

